def make(n):
    """Return a list of argument lists for Version("1.<i>") with i from 0 to n-1."""
    return [[f"1.{i}"] for i in range(min(n, 8))]

def make(n):
    # n distinct simple versions, each hashed once (cold cache)
    # return up to 8 argument lists; each list contains a single version string.
    # To make cost grow with n we return a single list containing n versions;
    # the benchmark will iterate over that list, creating and hashing each version.
    return [[f"1.{i}" for i in range(1, n + 1)]]

def make(n):
    chunks = []
    for i in range(1, n+1):
        chunks.append(str(i).zfill(i))
    version = '.'.join(chunks) + 'c5'
    return [(version,)]
